import{_ as l,a0 as i,w as d,s as m,ao as a,I as t,a1 as n,A as p,x as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在浏览器中启用深色模式 | LCTT x X-CMD","titleTemplate":false,"description":"如何在浏览器中启用深色模式 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在浏览器中启用深色模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在浏览器中启用深色模式 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220904 How to Enable Dark Mode in Web Browser","title":"如何在浏览器中启用深色模式","tag":"202209","desc":""},"relativePath":"202209/20220904 How to Enable Dark Mode in Web Browser.md","filePath":"[post].md"}'),s={name:"202209/20220904 How to Enable Dark Mode in Web Browser.md"};function u(b,e,h,f,g,w){const o=i("Link");return d(),m("div",null,[e[22]||(e[22]=a('<h1 id="如何在浏览器中启用深色模式" tabindex="-1">如何在浏览器中启用深色模式 <a class="header-anchor" href="#如何在浏览器中启用深色模式" aria-label="Permalink to “如何在浏览器中启用深色模式”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/15/232124u1ikykxri6oehx0h.jpg" alt=""></p><blockquote><p>本指南旨在帮助你了解如何在流行的浏览器，如 Firefox、谷歌 Chrome、Chromium 和微软 Edge 中启用深色模式。</p></blockquote><p>我们都喜欢深色模式。许多人喜欢它，而不是标准的浅色模式。虽然许多桌面应用提供了原生的深色模式，但一些应用通过桌面环境的基础模式适应深色模式。</p><p>你不能否认，我们都在浏览器上花了好多时间。我们很少使用桌面应用（除非你是在工作，如视频编辑等）。因此，当你在浏览器上花很多时间阅读和学习时，你应该也可以选择深色模式。但是，对于各个浏览器，稍微有点不同。</p><p>本指南为你提供简单的步骤，你可以按照这些步骤在 Mozilla Firefox、Chromium、Chrome 和 Edge 浏览器中启用深色模式。</p><h3 id="在浏览器中启用深色模式" tabindex="-1">在浏览器中启用深色模式 <a class="header-anchor" href="#在浏览器中启用深色模式" aria-label="Permalink to “在浏览器中启用深色模式”">​</a></h3><h4 id="在-firefox-中启用深色模式" tabindex="-1">在 Firefox 中启用深色模式 <a class="header-anchor" href="#在-firefox-中启用深色模式" aria-label="Permalink to “在 Firefox 中启用深色模式”">​</a></h4><p>打开 Firefox ，点击右上角的设置菜单。</p><p>点击 “<ruby>设置<rt>Settings</rt></ruby> &gt; <ruby>扩展和主题<rt>Extension and Themes</rt></ruby>”。</p><p>选择“<ruby>深色主题<rt>Dark Theme</rt></ruby>”并点击“<ruby>启用<rt>enable</rt></ruby>”。然后你应该看到深色模式被应用到 Firefox。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Enable-dark-mode-in-Firefox.jpg" alt="Enable dark mode in Firefox"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Firefox-in-Dark-Mode-1024x423.jpg" alt="Firefox in Dark Mode"></p><p>要恢复它，按照同样的步骤，选择浅色主题。</p><h4 id="chromium-和-chrome-的深色模式" tabindex="-1">Chromium 和 Chrome 的深色模式 <a class="header-anchor" href="#chromium-和-chrome-的深色模式" aria-label="Permalink to “Chromium 和 Chrome 的深色模式”">​</a></h4><p>Chromium 或 Chrome 默认不预装任何深色主题。因此，你需要去 Chrome 商店，下载任何你想要的深色主题。在本指南中，我将推荐 “Morpheon Dark” 主题，它有超过一百万用户在使用它。</p><p>从 Chromium 浏览器中打开 Morpheon Dark 主题页面（从以下链接）。</p>',17)),t("blockquote",null,[t("p",null,[t("strong",null,[n(o,{href:"https://chrome.google.com/webstore/detail/morpheon-dark/mafbdhjdkjnoafhfelkjpchpaepjknad?hl=en-GB"},{default:p(()=>[...e[0]||(e[0]=[r("Chrome 网络商店中的 Morpheon Dark 主题",-1)])]),_:1})])])]),e[23]||(e[23]=t("p",null,[r("点击“"),t("ruby",null,[r("添加到 Chrome"),t("rt",null,"Add To Chrome")]),r("” 按钮。它应该会在 Chrome 中启用。")],-1)),t("p",null,[e[2]||(e[2]=r("你可能想探索 Chrome 网络商店中的其他黑白或深色主题。",-1)),n(o,{href:"https://chrome.google.com/webstore/category/collection/dark_themes"},{default:p(()=>[...e[1]||(e[1]=[r("请访问此页面，查看所有的深色主题集合",-1)])]),_:1}),e[3]||(e[3]=r(" 。",-1))]),e[24]||(e[24]=t("p",null,"然而，你应该记住一件事：这个主题不会改变设置或上下文菜单。这很明显。因为它只是改变了浏览器窗口，而那些菜单是操作系统本身的一部分（有时）。",-1)),e[25]||(e[25]=t("p",null,[t("img",{src:"https://www.debugpoint.com/wp-content/uploads/2021/10/Chromium-Dark-Theme-1024x463.jpg",alt:"Chromium Dark Theme"})],-1)),e[26]||(e[26]=t("p",null,"对 Google Chrome 也要按照同样的步骤进行。",-1)),e[27]||(e[27]=t("h4",{id:"edge-浏览器的深色模式",tabindex:"-1"},[r("Edge 浏览器的深色模式 "),t("a",{class:"header-anchor",href:"#edge-浏览器的深色模式","aria-label":"Permalink to “Edge 浏览器的深色模式”"},"​")],-1)),t("p",null,[e[5]||(e[5]=r("然而，",-1)),n(o,{href:"https://www.debugpoint.com/2020/10/how-to-install-edge-ubuntu-linux/"},{default:p(()=>[...e[4]||(e[4]=[r("微软 Edge 浏览器",-1)])]),_:1}),e[6]||(e[6]=r(" 默认带有更好的深色主题。它允许你从设置中使用 GTK+、浅色和深色模式。",-1))]),e[28]||(e[28]=a('<p>打开 Edge 浏览器</p><p>点击右上角的三个小圆点。</p><p>进入“<ruby>外观<rt>Appearance</rt></ruby>”，选择“<ruby>深色<rt>Dark</rt></ruby>”。这就完成了。</p><p>这个 Edge 的深色主题实现得更好，因为它改变了上下文菜单和地址栏。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Edge-in-Dark-Theme-1024x541.jpg" alt="Edge in Dark Theme"></p><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to “结束语”">​</a></h3><p>如果你是一个高级用户，你可能不需要这个指南。你可以搞清楚。</p><p>但我们为所有的读者涵盖了所有从基础到高级的教程。许多新的 Linux 用户可能也不知道如何在浏览器中启用深色模式。</p><p>因此，话虽如此，我希望这能帮助你和其他人。如果你遇到任何麻烦，请在下面的评论栏里告诉我。</p><hr>',10)),t("p",null,[e[8]||(e[8]=r("via: ",-1)),n(o,{href:"https://www.debugpoint.com/dark-mode-browser/"},{default:p(()=>[...e[7]||(e[7]=[r("https://www.debugpoint.com/dark-mode-browser/",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=r("作者：",-1)),n(o,{href:"https://www.debugpoint.com/author/admin1/"},{default:p(()=>[...e[9]||(e[9]=[r("Arindam",-1)])]),_:1}),e[14]||(e[14]=r(" 选题：",-1)),n(o,{href:"https://github.com/lkxed"},{default:p(()=>[...e[10]||(e[10]=[r("lkxed",-1)])]),_:1}),e[15]||(e[15]=r(" 译者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:p(()=>[...e[11]||(e[11]=[r("geekpi",-1)])]),_:1}),e[16]||(e[16]=r(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:p(()=>[...e[12]||(e[12]=[r("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=r("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[17]||(e[17]=[r("LCTT",-1)])]),_:1}),e[20]||(e[20]=r(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:p(()=>[...e[18]||(e[18]=[r("Linux中国",-1)])]),_:1}),e[21]||(e[21]=r(" 荣誉推出",-1))])])}const T=l(s,[["render",u]]);export{C as __pageData,T as default};
